def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(val(ctx, 'task.task_type', ''))
    target = text(val(ctx, 'task.target_type', ''))
    dest = text(val(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(val(ctx, 'world.inventory', ''))
    if target and act.startswith('take ') and target in act and 'pick up' in obs:
        nb['carrying_target'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['carrying_target'] = False
    if target and verb and target in act and act.startswith(verb + ' ') and 'nothing happens' not in obs and 'cannot' not in obs:
        nb['transformed'] = True
    pc = val(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    if target and act.startswith('put ') and target in act and 'you put' in obs and dest and dest in act:
        nb['placed_count'] = nb.get('placed_count', 0) + 1
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and target and target not in inv and 'nothing' not in inv and 'not carrying' not in inv)
    admiss = [text(a) for a in (ctx.get('admissible') or [])]
    take_here = bool(target and any(a.startswith('take ') and target in a for a in admiss))
    put_here = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in admiss))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transformed'):
        stage = 'transform'
    elif carrying and put_here:
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif take_here:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    return None

