def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    tt = nb.get('task_type', '')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target object. Do not place it at the goal destination; recover by setting it aside only if needed, then find and take the requested ' + target + '.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target instead of continuing to search or handling other objects.'
    elif stage == 'transform' and target and verb:
        msg = 'You are carrying the ' + target + '. Use the admissible ' + verb + ' action before placing it; do not put it at the destination yet.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the admissible put action there.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the ' + dest + ' with the ' + target + '. Use the admissible put action to finish this placement.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) > 0 and target:
        msg = 'One ' + target + ' is already placed. Find another ' + target + ', do not take back the placed one, and use the same destination type.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

