def hook(ctx, nb):
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type', '')
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if not target or not act:
        return None
    if 'two' in tt and act.startswith('take ') and target in act:
        locs = text(val(ctx, 'world.placed_locations', ''))
        if locs and any(loc in act for loc in locs.split()):
            return {'kind': 'block_and_prompt', 'message': 'Do not take back a ' + target + ' that is already placed for the two-object task. Find another target item and use the same destination type.'}
    if act.startswith('put ') and target in act and dest and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Keep the ' + target + ' and go to a ' + dest + ' for the put action.'}
    return None
